apiIntegrations.responseShape:
interface JSONFeed {
  version: string;
  title: string;
  home_page_url?: string;
  feed_url?: string;
  icon?: string;
  items: Array<{
    id: string;
    url?: string;            // the instagram.com/p/XXX permalink
    title?: string;          // some bridges use this for captions
    content_text?: string;   // full caption as plain text
    content_html?: string;   // full caption as HTML
    image?: string;          // primary image URL for the post
    banner_image?: string;   // some bridges put the image here instead
    date_published?: string; // ISO 8601 timestamp
    attachments?: Array<{
      url: string;
      mime_type?: string;     // 'image/jpeg' for photos, 'video/mp4' for reels
      title?: string;
    }>;
  }>;
}
